def middle_two_pass(head):
    n = 0
    cur = head
    while cur:
        n += 1
        cur = cur.next
    cur = head
    for _ in range(n // 2):
        cur = cur.next
    return cur

def middle_node(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
    return slow
